// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address attacker, uint256 amount) public {
        vm.assume(attacker != address(0));
        amount = bound(amount, 0, 1 ether);

        Reverter rev = new Reverter();

        if (amount > 0) {
            vm.deal(address(this), amount);
            (bool sent, ) = address(c).call{value: amount}("");
            require(sent);
        }

        bool ok;
        try c.sendMoney(address(rev), amount, "") {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
